    n=>idea("Реши (1/3)^x ≥ 1/"+3**n+".","x ≤ "+n,["x ≥ "+n,"x < "+n,"x ≤ −"+n],"Основание между 0 и 1: знак у показателей меняется."),
    n=>idea("Реши 4^x < "+2**(2*n-1)+".","x < "+(2*n-1)+"/2",["x > "+(2*n-1)+"/2","x ≤ "+(2*n-1)+"/2","x < "+(2*n-1)],"Переход к основанию 2 даёт 2x < "+(2*n-1)+"."),
    n=>idea("Реши 3^("+signedExp(-n)+") ≤ 1.","x ≤ "+n,["x ≥ "+n,"x < "+n,"x ≤ −"+n],"Сравни с 3⁰: x − "+n+" ≤ 0.")
