      n=>idea(`Реши (x − ${n})⁴ − 5(x − ${n})² + 4 = 0.`,[n-2,n-1,n+1,n+2].join("; "),[[n-1,n+1].join("; "),[n-2,n+2].join("; "),[n+1,n+2].join("; ")],`Замена t = (x − ${n})² даёт t = 1 или 4. Из каждого квадрата получаем по два корня.`)
