    const scopedLimit = [7,8,9,14,17,18,20,28].includes(e.n) ? 7 : 14;
    const pool = [...new Map(Array.from({length:scopedLimit-2},(_,i)=>generator(i+3)).map(t=>[JSON.stringify(t.slice(0,3)),t])).values()];
