    const answerText = str(correct);
    const wrongText = [...new Set(wrong.map(str))].filter(x=>x!==answerText).slice(0,3);
    if(wrongText.length!==3) throw new Error("Invalid alternatives: "+q);
    const options = order([answerText,...wrongText],seed + Math.imul(701,attempt));
    return {q, options, answer:options.indexOf(answerText), explain, ...(e.skill?{skill:e.skill}:{}), ...(e.label?{topicLabel:e.label}:{})};
